"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[6095],{282(e){e.exports=JSON.parse('{"tag":{"label":"Correctness","permalink":"/concepts/tags/correctness","allTagsPath":"/concepts/tags","count":3,"items":[{"id":"mathematical-background/induction-and-recurrences","title":"Induction, Correctness and Recurrences","description":"Recursive algorithms raise two questions: is the algorithm correct, and how long does it take? The answer to both uses the same idea. A recursive algorithm solves a problem by trusting that the smaller calls work; mathematical induction is the tool that makes that trust rigorous, and a recurrence is the equation that describes its cost in terms of the cost of the smaller calls.","permalink":"/concepts/mathematical-background/induction-and-recurrences"},{"id":"foundations-of-algorithms/proofs","title":"Proofs: Foundations","description":"This page collects the proofs behind the claims of the chapter. The lessons state the results and use them; here they are justified. Each section is self-contained, and the lessons link to the section they need. The proof techniques (induction and loop invariants) are explained in Induction, Correctness and Recurrences.","permalink":"/concepts/foundations-of-algorithms/proofs"},{"id":"fundamental-problem-domains/proofs","title":"Proofs: Sorting","description":"This page proves the claims made in the sorting lessons: that each algorithm sorts correctly, the costs given in the lessons, and the limits that no comparison-based algorithm can break. The proofs use loop invariants and induction, explained in Induction, Correctness and Recurrences. Arrays are indexed from 0 and have $n$ elements.","permalink":"/concepts/fundamental-problem-domains/proofs"}],"unlisted":false}}')}}]);